window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-936ebf9e19ba7e52"]={"versions": [{"id": "FIG-936ebf9e19ba7e52", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Speicherabbildungs- und Adressierungsdiagramm der Flash EEPROM Emulation (FEE) in der AUTOSAR Classic Platform. Das Diagramm illustriert die zweistufige Adressierung und das Mapping logischer Speicherblöcke aus dem virtuellen 32-Bit-Adressraum auf den physischen Flash-Adressraum.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Virtual address space (Page size: 64 KBytes): 32-Bit-Adressraum, aufgeteilt in:\n<ul class=\"fig-list\"><li>16 Bit Block Number (Adressanteil zur Selektion eines logischen FEE-Blocks).\n</li><li>16 Bit Block Offset (Adressanteil innerhalb des Blocks bis maximal 64 KBytes).\n</li><li>Logische Datenblöcke: Block 1 (enthält Nutzdaten von 32 Bytes sowie freien/schraffierten Bereich), Block 2 (enthält Nutzdaten von 100 Bytes sowie freien Bereich), Block 3 (enthält Nutzdaten von 38 Bytes sowie freien Bereich).\n</li></ul>\n</li><li>Physical address space (Page size: 8 Bytes): Physischer Flash-Speicher, organisiert in festen 8-Byte-Pages.\n<ul class=\"fig-list\"><li>Physische Blockabbildungen mit Padding (internal residue):\n<ul class=\"fig-list\"><li>Block #1 (32 Bytes): belegt 4 Pages à 8 Bytes, 0 Bytes interner Rest.\n</li><li>Block #5 (100 Bytes): belegt 13 Pages (104 Bytes), 4 Bytes interner Rest.\n</li><li>Block #17 (38 Bytes): belegt 5 Pages (40 Bytes), 2 Bytes interner Rest.\n</li></ul>\n</li></ul>\n</li><li>Zuordnungsrelationen: Punktierte Projektionslinien verbinden die logischen Nutzdatenblöcke des virtuellen Speicherraums mit ihren fortlaufenden physischen Page-Allokationen im Flash.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Speicherstruktur dar. Die funktionale Zuordnung erfolgt über folgende Adressierungslogik:</p>\n<ol class=\"fig-list\"><li>Eine 32-Bit-FEE-Adresse setzt sich aus der höherwertigen 16-Bit-Blocknummer und dem niederwertigen 16-Bit-Block-Offset zusammen.\n</li><li>Der Block-Offset adressiert linear Daten innerhalb der virtuellen Blockgröße von bis zu 64 KBytes.\n</li><li>Bei der Übertragung in den physischen Flash-Speicher werden die Nutzdaten eines Blocks ganzzahlig auf physische Pages à 8 Bytes aufgerundet (Ceil-Funktion: <code>Anzahl_Pages = ceil(Blockgroesse / 8)</code>).\n</li><li>Nicht ganzzahlige Vielfache der 8-Byte-Pagegröße erzeugen am Ende des Blocks ungenutzten Speicherverschnitt (internal residue), der mit Padding aufgefüllt wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Adressierungsschema erzwingt eine maximale Blockgröße von 64 KByte pro logischem FEE-Block aufgrund der 16-Bit-Offset-Breite.\n</li><li>Die minimale Programmiergranularität im physischen Speicher beträgt 8 Bytes (physische Page-Größe).\n</li><li>FEE-Implementierungen müssen internes Padding vorsehen, wenn die konfigurierte Blockgröße kein ganzzahliges Vielfaches der physischen Flash-Page-Größe ist.\n</li><li>Die Größenverhältnisse im Schaubild sind laut Hinweis „Note: Sizes not shown to scale“ nicht maßstabsgetreu gezeichnet.\n</li></ul>"}, {"id": "FIG-46ee1b5e3d366acb", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Speicherabbildungs- und Adressierungsdiagramm der Flash EEPROM Emulation (FEE) in der AUTOSAR Classic Platform. Das Diagramm illustriert die zweistufige Adressierung und das Mapping logischer Speicherblöcke aus dem virtuellen 32-Bit-Adressraum auf den physischen Flash-Adressraum.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Virtual address space (Page size: 64 KBytes): 32-Bit-Adressraum, aufgeteilt in:\n<ul class=\"fig-list\"><li>16 Bit Block Number (Adressanteil zur Selektion eines logischen FEE-Blocks).\n</li><li>16 Bit Block Offset (Adressanteil innerhalb des Blocks bis maximal 64 KBytes).\n</li><li>Logische Datenblöcke: Block 1 (enthält Nutzdaten von 32 Bytes sowie freien/schraffierten Bereich), Block 2 (enthält Nutzdaten von 100 Bytes sowie freien Bereich), Block 3 (enthält Nutzdaten von 38 Bytes sowie freien Bereich).\n</li></ul>\n</li><li>Physical address space (Page size: 8 Bytes): Physischer Flash-Speicher, organisiert in festen 8-Byte-Pages.\n<ul class=\"fig-list\"><li>Physische Blockabbildungen mit Padding (internal residue):\n<ul class=\"fig-list\"><li>Block #1 (32 Bytes): belegt 4 Pages à 8 Bytes, 0 Bytes interner Rest.\n</li><li>Block #5 (100 Bytes): belegt 13 Pages (104 Bytes), 4 Bytes interner Rest.\n</li><li>Block #17 (38 Bytes): belegt 5 Pages (40 Bytes), 2 Bytes interner Rest.\n</li></ul>\n</li></ul>\n</li><li>Zuordnungsrelationen: Punktierte Projektionslinien verbinden die logischen Nutzdatenblöcke des virtuellen Speicherraums mit ihren fortlaufenden physischen Page-Allokationen im Flash.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Speicherstruktur dar. Die funktionale Zuordnung erfolgt über folgende Adressierungslogik:</p>\n<ol class=\"fig-list\"><li>Eine 32-Bit-FEE-Adresse setzt sich aus der höherwertigen 16-Bit-Blocknummer und dem niederwertigen 16-Bit-Block-Offset zusammen.\n</li><li>Der Block-Offset adressiert linear Daten innerhalb der virtuellen Blockgröße von bis zu 64 KBytes.\n</li><li>Bei der Übertragung in den physischen Flash-Speicher werden die Nutzdaten eines Blocks ganzzahlig auf physische Pages à 8 Bytes aufgerundet (Ceil-Funktion: <code>Anzahl_Pages = ceil(Blockgroesse / 8)</code>).\n</li><li>Nicht ganzzahlige Vielfache der 8-Byte-Pagegröße erzeugen am Ende des Blocks ungenutzten Speicherverschnitt (internal residue), der mit Padding aufgefüllt wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Adressierungsschema erzwingt eine maximale Blockgröße von 64 KByte pro logischem FEE-Block aufgrund der 16-Bit-Offset-Breite.\n</li><li>Die minimale Programmiergranularität im physischen Speicher beträgt 8 Bytes (physische Page-Größe).\n</li><li>FEE-Implementierungen müssen internes Padding vorsehen, wenn die konfigurierte Blockgröße kein ganzzahliges Vielfaches der physischen Flash-Page-Größe ist.\n</li><li>Die Größenverhältnisse im Schaubild sind laut Hinweis „Note: Sizes not shown to scale“ nicht maßstabsgetreu gezeichnet.\n</li></ul>"}, {"id": "FIG-1434724af11dd562", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Speicherabbildungs- und Adressierungsdiagramm der Flash EEPROM Emulation (FEE) in der AUTOSAR Classic Platform. Das Diagramm illustriert die zweistufige Adressierung und das Mapping logischer Speicherblöcke aus dem virtuellen 32-Bit-Adressraum auf den physischen Flash-Adressraum.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Virtual address space (Page size: 64 KBytes): 32-Bit-Adressraum, aufgeteilt in:\n<ul class=\"fig-list\"><li>16 Bit Block Number (Adressanteil zur Selektion eines logischen FEE-Blocks).\n</li><li>16 Bit Block Offset (Adressanteil innerhalb des Blocks bis maximal 64 KBytes).\n</li><li>Logische Datenblöcke: Block 1 (enthält Nutzdaten von 32 Bytes sowie freien/schraffierten Bereich), Block 2 (enthält Nutzdaten von 100 Bytes sowie freien Bereich), Block 3 (enthält Nutzdaten von 38 Bytes sowie freien Bereich).\n</li></ul>\n</li><li>Physical address space (Page size: 8 Bytes): Physischer Flash-Speicher, organisiert in festen 8-Byte-Pages.\n<ul class=\"fig-list\"><li>Physische Blockabbildungen mit Padding (internal residue):\n<ul class=\"fig-list\"><li>Block #1 (32 Bytes): belegt 4 Pages à 8 Bytes, 0 Bytes interner Rest.\n</li><li>Block #5 (100 Bytes): belegt 13 Pages (104 Bytes), 4 Bytes interner Rest.\n</li><li>Block #17 (38 Bytes): belegt 5 Pages (40 Bytes), 2 Bytes interner Rest.\n</li></ul>\n</li></ul>\n</li><li>Zuordnungsrelationen: Punktierte Projektionslinien verbinden die logischen Nutzdatenblöcke des virtuellen Speicherraums mit ihren fortlaufenden physischen Page-Allokationen im Flash.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Speicherstruktur dar. Die funktionale Zuordnung erfolgt über folgende Adressierungslogik:</p>\n<ol class=\"fig-list\"><li>Eine 32-Bit-FEE-Adresse setzt sich aus der höherwertigen 16-Bit-Blocknummer und dem niederwertigen 16-Bit-Block-Offset zusammen.\n</li><li>Der Block-Offset adressiert linear Daten innerhalb der virtuellen Blockgröße von bis zu 64 KBytes.\n</li><li>Bei der Übertragung in den physischen Flash-Speicher werden die Nutzdaten eines Blocks ganzzahlig auf physische Pages à 8 Bytes aufgerundet (Ceil-Funktion: <code>Anzahl_Pages = ceil(Blockgroesse / 8)</code>).\n</li><li>Nicht ganzzahlige Vielfache der 8-Byte-Pagegröße erzeugen am Ende des Blocks ungenutzten Speicherverschnitt (internal residue), der mit Padding aufgefüllt wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Adressierungsschema erzwingt eine maximale Blockgröße von 64 KByte pro logischem FEE-Block aufgrund der 16-Bit-Offset-Breite.\n</li><li>Die minimale Programmiergranularität im physischen Speicher beträgt 8 Bytes (physische Page-Größe).\n</li><li>FEE-Implementierungen müssen internes Padding vorsehen, wenn die konfigurierte Blockgröße kein ganzzahliges Vielfaches der physischen Flash-Page-Größe ist.\n</li><li>Die Größenverhältnisse im Schaubild sind laut Hinweis „Note: Sizes not shown to scale“ nicht maßstabsgetreu gezeichnet.\n</li></ul>"}, {"id": "FIG-ace984e71152c614", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Speicherabbildungs- und Adressierungsdiagramm der Flash EEPROM Emulation (FEE) in der AUTOSAR Classic Platform. Das Diagramm illustriert die zweistufige Adressierung und das Mapping logischer Speicherblöcke aus dem virtuellen 32-Bit-Adressraum auf den physischen Flash-Adressraum.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Virtual address space (Page size: 64 KBytes): 32-Bit-Adressraum, aufgeteilt in:\n<ul class=\"fig-list\"><li>16 Bit Block Number (Adressanteil zur Selektion eines logischen FEE-Blocks).\n</li><li>16 Bit Block Offset (Adressanteil innerhalb des Blocks bis maximal 64 KBytes).\n</li><li>Logische Datenblöcke: Block 1 (enthält Nutzdaten von 32 Bytes sowie freien/schraffierten Bereich), Block 2 (enthält Nutzdaten von 100 Bytes sowie freien Bereich), Block 3 (enthält Nutzdaten von 38 Bytes sowie freien Bereich).\n</li></ul>\n</li><li>Physical address space (Page size: 8 Bytes): Physischer Flash-Speicher, organisiert in festen 8-Byte-Pages.\n<ul class=\"fig-list\"><li>Physische Blockabbildungen mit Padding (internal residue):\n<ul class=\"fig-list\"><li>Block #1 (32 Bytes): belegt 4 Pages à 8 Bytes, 0 Bytes interner Rest.\n</li><li>Block #5 (100 Bytes): belegt 13 Pages (104 Bytes), 4 Bytes interner Rest.\n</li><li>Block #17 (38 Bytes): belegt 5 Pages (40 Bytes), 2 Bytes interner Rest.\n</li></ul>\n</li></ul>\n</li><li>Zuordnungsrelationen: Punktierte Projektionslinien verbinden die logischen Nutzdatenblöcke des virtuellen Speicherraums mit ihren fortlaufenden physischen Page-Allokationen im Flash.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Speicherstruktur dar. Die funktionale Zuordnung erfolgt über folgende Adressierungslogik:</p>\n<ol class=\"fig-list\"><li>Eine 32-Bit-FEE-Adresse setzt sich aus der höherwertigen 16-Bit-Blocknummer und dem niederwertigen 16-Bit-Block-Offset zusammen.\n</li><li>Der Block-Offset adressiert linear Daten innerhalb der virtuellen Blockgröße von bis zu 64 KBytes.\n</li><li>Bei der Übertragung in den physischen Flash-Speicher werden die Nutzdaten eines Blocks ganzzahlig auf physische Pages à 8 Bytes aufgerundet (Ceil-Funktion: <code>Anzahl_Pages = ceil(Blockgroesse / 8)</code>).\n</li><li>Nicht ganzzahlige Vielfache der 8-Byte-Pagegröße erzeugen am Ende des Blocks ungenutzten Speicherverschnitt (internal residue), der mit Padding aufgefüllt wird.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Das Adressierungsschema erzwingt eine maximale Blockgröße von 64 KByte pro logischem FEE-Block aufgrund der 16-Bit-Offset-Breite.\n</li><li>Die minimale Programmiergranularität im physischen Speicher beträgt 8 Bytes (physische Page-Größe).\n</li><li>FEE-Implementierungen müssen internes Padding vorsehen, wenn die konfigurierte Blockgröße kein ganzzahliges Vielfaches der physischen Flash-Page-Größe ist.\n</li><li>Die Größenverhältnisse im Schaubild sind laut Hinweis „Note: Sizes not shown to scale“ nicht maßstabsgetreu gezeichnet.\n</li></ul>"}], "trans": [{"from": "FIG-936ebf9e19ba7e52", "to": "FIG-46ee1b5e3d366acb", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-46ee1b5e3d366acb", "to": "FIG-1434724af11dd562", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1434724af11dd562", "to": "FIG-ace984e71152c614", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Dokumenten-Header: Außerhalb des Diagrammrahmens oben rechts wurden Versions- und Release-Kennzeichnungen („V1.5.0“ und „R3.2 Rev 3“) hinzugefügt.\n</li></ul>"}]};
